import sys
from collections import defaultdict

def find_longest_path(graph, start):
    visited = set()
    def dfs(node, parent):
        longest = []
        for neighbor in graph[node]:
            if neighbor != parent:
                path = [node] + dfs(neighbor, node)
                if len(path) > len(longest):
                    longest = path
        return longest
    return dfs(start, None)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[i * 2 + 1]), int(input[i * 2 + 2])) for i in range(n - 1)]

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    longest_path = find_longest_path(graph, 1)
    paths = []
    for i in range(len(longest_path) - 1):
        u, v = longest_path[i], longest_path[i + 1]
        edge_index = edges.index((u, v)) + 1 if (u, v) in edges else edges.index((v, u)) + 1
        paths.append((1, [edge_index], u, v, 1/3))

    print(len(paths))
    for path in paths:
        print(*path)

if __name__ == "__main__":
    main()
